alter table public.boards enable row level security;
alter table public.board_members enable row level security;
alter table public.cards enable row level security;

create or replace function public.is_board_member(p_board_id bigint, p_role text default null)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members bm
    where bm.board_id = p_board_id
      and bm.user_id = auth.uid()
      and (p_role is null or bm.role = p_role)
  );
$$;

create or replace function public.board_is_archived(p_board_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.boards b
    where b.id = p_board_id
      and b.is_archived = true
  );
$$;

create or replace function public.can_edit_card(p_card_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.cards c
    join public.board_members bm on bm.board_id = c.board_id
    where c.id = p_card_id
      and bm.user_id = auth.uid()
      and bm.role = 'editor'
      and not public.board_is_archived(c.board_id)
  );
$$;

create or replace function public.can_create_card(p_board_id bigint, p_column_name text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1
    from public.board_members bm
    where bm.board_id = p_board_id
      and bm.user_id = auth.uid()
      and bm.role = 'editor'
      and not public.board_is_archived(p_board_id)
  )
  and p_column_name in ('todo', 'doing', 'done');
$$;

create or replace function public.enforce_card_editor_target()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.board_id is distinct from old.board_id
     or new.title is distinct from old.title
     or new.assignee_id is distinct from old.assignee_id then
    if not public.can_edit_card(old.id) then
      raise exception 'only editors can modify cards';
    end if;
    return new;
  end if;

  if new.column_name is distinct from old.column_name then
    if not public.can_edit_card(old.id) then
      raise exception 'only editors can modify cards';
    end if;
    if not exists (
      select 1
      from public.board_members bm
      where bm.board_id = new.board_id
        and bm.user_id = auth.uid()
        and bm.role = 'editor'
        and not public.board_is_archived(new.board_id)
    ) then
      raise exception 'card can only be moved to a board where the user is an editor';
    end if;
    return new;
  end if;

  return new;
end;
$$;

