```sql
alter table public.org_admins enable row level security;
alter table public.files enable row level security;

-- Helper function to check if current user is an org admin
create or replace function public.is_org_admin(check_user_id uuid default auth.uid())
returns boolean as $$
begin
  return exists (
    select 1 from public.org_admins where user_id = check_user_id
  );
end;
$$ language plpgsql security definer;

-- Helper function to check if a file is under legal hold
create or replace function public.is_file_in_legal_hold(file_id bigint)
returns boolean as $$
begin
  return exists (
    select 1 from public.files where id = file_id and legal_hold = true
  );
end;
$$ language plpgsql security definer;

-- org_admins policies
create policy "org_admins_select_all"
  on public.org_admins
  for select
  to authenticated
  using (true);

create policy "org_admins_no_insert"
  on public.org_admins
  for insert
  to authenticated
  with check (false);

create policy "org_admins_no_update"
  on public.org_admins
